/* ========================================
   GreenBean Coffee — Design System
   Colors: #00824A (green), #32462F (forest), #F3CEA1 (cream)
   Typography: Inter + DM Serif Display
   ======================================== */

@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --green: #00824A;
  --green-dark: #006838;
  --green-light: #e6f5ed;
  --forest: #32462F;
  --forest-light: #4a6345;
  --cream: #F3CEA1;
  --cream-light: #faf3e0;
  --cream-dark: #e8c278;
  --brown: #6F4E37;
  --brown-light: #8B6F47;
  --white: #FFFFFF;
  --off-white: #f9f7f4;
  --gray-50: #fafafa;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'DM Serif Display', Georgia, serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.12);
  --shadow-xl: 0 16px 40px rgba(0,0,0,0.16);
  --max-width: 1280px;
  --header-height: 72px;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body { font-family: var(--font-body); color: var(--gray-800); line-height: 1.6; background: var(--white); }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
input, select, textarea { font-family: inherit; font-size: inherit; }

/* Typography */
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: 400; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.125rem; }
p { max-width: 65ch; }

/* Utility Classes */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full); font-weight: 600;
  font-size: 0.9375rem; transition: all 0.2s ease; white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-secondary { background: var(--white); color: var(--green); border: 1.5px solid var(--green); }
.btn-secondary:hover { background: var(--green-light); }
.btn-cream { background: var(--cream); color: var(--forest); }
.btn-cream:hover { background: var(--cream-dark); }
.btn-forest { background: var(--forest); color: var(--cream); }
.btn-forest:hover { background: var(--forest-light); }
.btn-sm { padding: 8px 20px; font-size: 0.875rem; }
.btn-lg { padding: 16px 36px; font-size: 1rem; }

/* ==================== HEADER ==================== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--white); border-bottom: 1px solid var(--gray-200);
  height: var(--header-height);
}
.header-inner {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; justify-content: space-between; height: 100%;
}
.logo { display: flex; align-items: center; gap: 8px; font-family: var(--font-heading); font-size: 1.5rem; color: var(--green); }
.logo-icon { width: 36px; height: 36px; background: var(--green); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--white); font-size: 1.125rem; }
.nav-primary { display: flex; align-items: center; gap: 32px; }
.nav-primary a { font-weight: 500; color: var(--gray-700); transition: color 0.2s; font-size: 0.9375rem; }
.nav-primary a:hover { color: var(--green); }
.nav-account { display: flex; align-items: center; gap: 16px; }
.nav-account a { font-size: 0.875rem; font-weight: 500; color: var(--gray-600); }
.nav-account a:hover { color: var(--green); }
.nav-account .btn { font-size: 0.875rem; padding: 8px 20px; }
.mobile-menu-btn { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; }
.hamburger { width: 24px; height: 2px; background: var(--gray-700); position: relative; transition: all 0.3s; }
.hamburger::before, .hamburger::after { content: ''; position: absolute; width: 24px; height: 2px; background: var(--gray-700); transition: all 0.3s; }
.hamburger::before { top: -7px; }
.hamburger::after { top: 7px; }
.mobile-nav { display: none; position: fixed; top: var(--header-height); left: 0; right: 0; bottom: 0; background: var(--white); z-index: 99; padding: 24px; }
.mobile-nav.active { display: block; }
.mobile-nav a { display: block; padding: 16px 0; font-size: 1.25rem; font-weight: 500; color: var(--gray-700); border-bottom: 1px solid var(--gray-200); }

/* ==================== FOOTER ==================== */
.site-footer { background: var(--forest); color: var(--cream-light); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px; margin-bottom: 48px; }
.footer-col h4 { color: var(--white); font-family: var(--font-body); font-weight: 700; font-size: 0.9375rem; margin-bottom: 16px; cursor: default; }
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a { color: var(--cream-light); font-size: 0.875rem; opacity: 0.85; transition: opacity 0.2s; }
.footer-col ul li a:hover { opacity: 1; }
.footer-bottom { border-top: 1px solid rgba(243,206,161,0.2); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
.footer-bottom p { font-size: 0.8125rem; opacity: 0.7; }
.footer-social { display: flex; gap: 16px; }
.footer-social a { width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; font-size: 0.875rem; transition: background 0.2s; }
.footer-social a:hover { background: rgba(255,255,255,0.2); }

/* Footer accordion (mobile) */
.footer-accordion-toggle { display: none; width: 100%; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid rgba(243,206,161,0.15); }
.footer-accordion-toggle h4 { margin-bottom: 0; }
.footer-accordion-toggle .chevron { transition: transform 0.3s; font-size: 0.75rem; }
.footer-accordion-toggle.active .chevron { transform: rotate(180deg); }
.footer-col-content { overflow: hidden; transition: max-height 0.3s ease; }
.footer-col-content.collapsed { max-height: 0 !important; }

/* ==================== COOKIE BANNER ==================== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--forest); color: var(--cream-light); padding: 20px 24px;
  display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
}
.cookie-banner.hidden { display: none; }
.cookie-banner p { font-size: 0.875rem; max-width: 600px; }
.cookie-banner .btn { font-size: 0.8125rem; padding: 8px 20px; }

/* ==================== HERO ==================== */
.hero {
  background: linear-gradient(135deg, var(--green-light) 0%, var(--cream-light) 100%);
  padding: 80px 0; position: relative; overflow: hidden;
}
.hero-inner { display: flex; align-items: center; gap: 48px; }
.hero-text { flex: 1; }
.hero-text h1 { margin-bottom: 16px; color: var(--forest); }
.hero-text p { font-size: 1.125rem; color: var(--gray-600); margin-bottom: 32px; max-width: 480px; }
.hero-image { flex: 1; display: flex; justify-content: center; }
.hero-image-placeholder {
  width: 100%; max-width: 480px; aspect-ratio: 1; border-radius: var(--radius-xl);
  background: linear-gradient(145deg, var(--cream) 0%, var(--cream-dark) 100%);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.5rem; color: var(--brown);
  box-shadow: var(--shadow-lg);
}

/* ==================== SECTION STYLES ==================== */
.section { padding: 80px 0; }
.section-cream { background: var(--cream-light); }
.section-green { background: var(--green-light); }
.section-forest { background: var(--forest); color: var(--cream-light); }
.section-forest h2, .section-forest h3 { color: var(--white); }

.section-header { margin-bottom: 48px; }
.section-header h2 { margin-bottom: 12px; }
.section-header p { font-size: 1.0625rem; color: var(--gray-500); max-width: 560px; }

/* ==================== PROMO CARDS ==================== */
.promo-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.promo-card {
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white); box-shadow: var(--shadow-md);
  transition: transform 0.2s, box-shadow 0.2s;
}
.promo-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.promo-card-image {
  height: 240px; display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.25rem; color: var(--brown);
}
.promo-card-body { padding: 28px; }
.promo-card-body h3 { margin-bottom: 8px; color: var(--forest); }
.promo-card-body p { font-size: 0.9375rem; color: var(--gray-500); margin-bottom: 20px; }

/* ==================== SEASONAL HIGHLIGHTS ==================== */
.seasonal-split { display: grid; grid-template-columns: 1fr 1fr; gap: 0; min-height: 480px; border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-lg); }
.seasonal-image {
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.5rem; color: var(--brown);
}
.seasonal-content { padding: 48px; display: flex; flex-direction: column; justify-content: center; }
.seasonal-content h2 { margin-bottom: 16px; color: var(--forest); }
.seasonal-content p { font-size: 1.0625rem; color: var(--gray-500); margin-bottom: 28px; }

/* ==================== MENU PAGE ==================== */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 0; min-height: calc(100vh - var(--header-height)); }
.menu-sidebar {
  background: var(--off-white); border-right: 1px solid var(--gray-200);
  padding: 32px 24px; position: sticky; top: var(--header-height); height: calc(100vh - var(--header-height)); overflow-y: auto;
}
.menu-sidebar h4 { font-family: var(--font-body); font-weight: 700; font-size: 0.8125rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 12px; margin-top: 24px; }
.menu-sidebar h4:first-child { margin-top: 0; }
.menu-sidebar a { display: block; padding: 8px 12px; border-radius: var(--radius-sm); font-size: 0.9375rem; color: var(--gray-600); transition: all 0.15s; margin-bottom: 2px; }
.menu-sidebar a:hover { background: var(--green-light); color: var(--green); }
.menu-sidebar a.active { background: var(--green); color: var(--white); font-weight: 500; }
.menu-main { padding: 32px 48px; }
.menu-section { margin-bottom: 56px; }
.menu-section h2 { margin-bottom: 8px; color: var(--forest); }
.menu-section > p { color: var(--gray-500); margin-bottom: 28px; }
.menu-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 20px; }
.menu-item { text-align: center; }
.menu-item-img {
  width: 100%; aspect-ratio: 1; border-radius: var(--radius-md);
  background: var(--cream-light); display: flex; align-items: center; justify-content: center;
  font-size: 2rem; margin-bottom: 12px; transition: transform 0.2s;
}
.menu-item-img:hover { transform: scale(1.05); }
.menu-item h4 { font-family: var(--font-body); font-weight: 600; font-size: 0.9375rem; color: var(--gray-700); }

/* Breadcrumb */
.breadcrumb { padding: 16px 48px; background: var(--off-white); border-bottom: 1px solid var(--gray-200); }
.breadcrumb-inner { display: flex; align-items: center; gap: 8px; font-size: 0.875rem; color: var(--gray-500); }
.breadcrumb-inner a { color: var(--green); }
.breadcrumb-inner .sep { color: var(--gray-300); }

/* ==================== REWARDS PAGE ==================== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green) 0%, #00a85e 100%);
  padding: 80px 0; color: var(--white); text-align: center;
}
.rewards-hero h1 { margin-bottom: 16px; }
.rewards-hero p { font-size: 1.125rem; opacity: 0.9; margin: 0 auto 32px; max-width: 520px; }

.how-it-works { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; text-align: center; }
.how-step { padding: 32px; }
.how-step-number {
  width: 56px; height: 56px; border-radius: 50%; background: var(--green);
  color: var(--white); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1.25rem; margin: 0 auto 20px;
}
.how-step h3 { margin-bottom: 8px; color: var(--forest); }
.how-step p { font-size: 0.9375rem; color: var(--gray-500); }

/* Status Tiers */
.tier-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tier-card {
  border-radius: var(--radius-lg); padding: 36px 28px; position: relative; overflow: hidden;
  border: 2px solid var(--gray-200); transition: border-color 0.2s, box-shadow 0.2s;
}
.tier-card:hover { border-color: var(--green); box-shadow: var(--shadow-md); }
.tier-card.gold-card { border-color: var(--cream-dark); }
.tier-card.gold-card:hover { border-color: #d4a843; }
.tier-card.reserve-card { border-color: var(--forest); background: var(--forest); color: var(--cream-light); }
.tier-card.reserve-card:hover { box-shadow: var(--shadow-lg); }
.tier-badge {
  display: inline-block; padding: 4px 16px; border-radius: var(--radius-full);
  font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
  margin-bottom: 16px;
}
.tier-badge.green-badge { background: var(--green-light); color: var(--green); }
.tier-badge.gold-badge { background: var(--cream); color: #8B6914; }
.tier-badge.reserve-badge { background: rgba(255,255,255,0.15); color: var(--cream); }
.tier-card h3 { margin-bottom: 4px; }
.tier-card .tier-threshold { font-size: 0.875rem; color: var(--gray-400); margin-bottom: 20px; }
.tier-card.reserve-card .tier-threshold { color: rgba(243,206,161,0.6); }
.tier-card ul { font-size: 0.9375rem; }
.tier-card ul li { padding: 6px 0; display: flex; align-items: flex-start; gap: 8px; }
.tier-card ul li::before { content: '★'; color: var(--cream-dark); flex-shrink: 0; }
.tier-card.reserve-card ul li::before { color: var(--cream); }

/* Redemption Tabs */
.redemption-tabs { margin-top: 48px; }
.tab-list {
  display: flex; gap: 4px; border-bottom: 2px solid var(--gray-200);
  overflow-x: auto; -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.tab-list::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 14px 20px; font-weight: 600; font-size: 0.9375rem;
  color: var(--gray-500); border-bottom: 3px solid transparent;
  transition: all 0.2s; white-space: nowrap; margin-bottom: -2px;
}
.tab-btn:hover { color: var(--green); }
.tab-btn.active { color: var(--green); border-bottom-color: var(--green); }
.tab-panel { display: none; padding: 32px 0; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.redemption-card {
  display: flex; align-items: center; gap: 32px;
  padding: 32px; background: var(--white); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm); border: 1px solid var(--gray-200);
}
.redemption-icon {
  width: 120px; height: 120px; border-radius: var(--radius-md);
  background: var(--cream-light); display: flex; align-items: center; justify-content: center;
  font-size: 3rem; flex-shrink: 0;
}
.redemption-info h3 { margin-bottom: 4px; color: var(--forest); }
.redemption-info .reward-desc { font-size: 1rem; color: var(--gray-600); margin-bottom: 4px; }
.redemption-info .reward-value { font-size: 0.875rem; color: var(--green); font-weight: 600; }

/* Partnerships */
.partnership-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.partnership-card {
  padding: 36px; border-radius: var(--radius-lg); border: 1px solid var(--gray-200);
  display: flex; align-items: center; gap: 24px; transition: box-shadow 0.2s;
}
.partnership-card:hover { box-shadow: var(--shadow-md); }
.partner-logo {
  width: 64px; height: 64px; border-radius: var(--radius-md);
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1.5rem; color: var(--gray-600); flex-shrink: 0;
}
.partnership-card h3 { font-size: 1.125rem; margin-bottom: 4px; color: var(--forest); }
.partnership-card p { font-size: 0.9375rem; color: var(--gray-500); }

/* App Download */
.app-download {
  background: linear-gradient(135deg, var(--green) 0%, #00a85e 100%);
  border-radius: var(--radius-xl); padding: 56px; display: flex; align-items: center;
  justify-content: space-between; gap: 40px; color: var(--white);
}
.app-download h2 { margin-bottom: 12px; }
.app-download p { opacity: 0.9; font-size: 1.0625rem; max-width: 480px; }
.app-buttons { display: flex; gap: 12px; }
.app-btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 24px; background: var(--white); color: var(--green);
  border-radius: var(--radius-sm); font-weight: 600; font-size: 0.9375rem;
  transition: transform 0.2s;
}
.app-btn:hover { transform: translateY(-2px); }

/* ==================== GIFT PAGE ==================== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream-light) 0%, #fde8c8 100%);
  padding: 80px 0; text-align: center;
}
.gift-hero h1 { margin-bottom: 16px; color: var(--forest); }
.gift-hero p { font-size: 1.125rem; color: var(--gray-500); max-width: 560px; margin: 0 auto 32px; }

/* Carousel */
.carousel-section { margin-bottom: 56px; }
.carousel-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
.carousel-header h3 { color: var(--forest); }
.carousel-nav { display: flex; gap: 8px; }
.carousel-nav button {
  width: 40px; height: 40px; border-radius: 50%; border: 1.5px solid var(--gray-300);
  display: flex; align-items: center; justify-content: center; font-size: 1.125rem;
  color: var(--gray-600); transition: all 0.2s; background: var(--white);
}
.carousel-nav button:hover { border-color: var(--green); color: var(--green); background: var(--green-light); }

.carousel-track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex; gap: 16px; transition: transform 0.4s cubic-bezier(0.25, 0.1, 0.25, 1);
}
.gift-card {
  min-width: 200px; flex-shrink: 0; cursor: pointer;
  transition: transform 0.2s;
}
.gift-card:hover { transform: translateY(-4px); }
.gift-card-img {
  width: 200px; height: 130px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.8125rem; font-weight: 600; color: var(--white);
  margin-bottom: 8px; box-shadow: var(--shadow-md);
}
.gift-card-name { font-size: 0.8125rem; color: var(--gray-600); text-align: center; }

/* Category section */
.category-section { margin-bottom: 48px; }

/* Business gifting */
.business-gifting {
  display: flex; align-items: center; gap: 48px;
  padding: 56px; background: var(--forest); border-radius: var(--radius-xl); color: var(--cream-light);
}
.business-gifting h2 { color: var(--white); margin-bottom: 12px; }
.business-gifting p { opacity: 0.85; font-size: 1.0625rem; margin-bottom: 24px; max-width: 520px; }

/* eGift Info */
.egift-info { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start; }
.egift-text h3 { margin-bottom: 16px; color: var(--forest); }
.egift-text p { font-size: 0.9375rem; color: var(--gray-500); margin-bottom: 12px; }
.egift-links { display: flex; flex-wrap: wrap; gap: 16px; }
.egift-links a { color: var(--green); font-weight: 500; font-size: 0.9375rem; }
.egift-links a:hover { text-decoration: underline; }

/* FAQ */
.faq-list { max-width: 720px; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  width: 100%; padding: 20px 0; display: flex; justify-content: space-between;
  align-items: center; font-size: 1rem; font-weight: 500; color: var(--gray-700);
  text-align: left;
}
.faq-question .faq-icon { transition: transform 0.3s; font-size: 1.25rem; color: var(--gray-400); }
.faq-question.active .faq-icon { transform: rotate(45deg); }
.faq-answer { padding: 0 0 20px; font-size: 0.9375rem; color: var(--gray-500); display: none; }
.faq-answer.active { display: block; }

/* ==================== STORE LOCATOR ==================== */
.locator-layout { display: grid; grid-template-columns: 400px 1fr; min-height: calc(100vh - var(--header-height)); }
.locator-sidebar { background: var(--white); border-right: 1px solid var(--gray-200); display: flex; flex-direction: column; }

.search-controls { padding: 20px; border-bottom: 1px solid var(--gray-200); }
.search-input-wrap { display: flex; gap: 8px; margin-bottom: 12px; }
.search-input {
  flex: 1; padding: 12px 16px; border: 1.5px solid var(--gray-300); border-radius: var(--radius-full);
  font-size: 0.9375rem; outline: none; transition: border-color 0.2s;
}
.search-input:focus { border-color: var(--green); }
.search-input::placeholder { color: var(--gray-400); }
.search-btn {
  width: 44px; height: 44px; border-radius: 50%; background: var(--green);
  color: var(--white); display: flex; align-items: center; justify-content: center;
  font-size: 1.125rem; transition: background 0.2s;
}
.search-btn:hover { background: var(--green-dark); }

.search-filters { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.filter-btn {
  padding: 8px 16px; border-radius: var(--radius-full); border: 1.5px solid var(--gray-300);
  font-size: 0.8125rem; font-weight: 500; color: var(--gray-600); transition: all 0.2s;
  display: flex; align-items: center; gap: 4px;
}
.filter-btn:hover { border-color: var(--green); color: var(--green); }
.filter-btn.active { background: var(--green); color: var(--white); border-color: var(--green); }

.order-type-toggle {
  display: flex; background: var(--gray-100); border-radius: var(--radius-full); padding: 3px;
}
.order-type-btn {
  flex: 1; padding: 8px 20px; border-radius: var(--radius-full); font-size: 0.875rem;
  font-weight: 500; color: var(--gray-500); text-align: center; transition: all 0.2s;
}
.order-type-btn.active { background: var(--white); color: var(--green); box-shadow: var(--shadow-sm); }

.filter-panel {
  padding: 16px 20px; background: var(--off-white); border-bottom: 1px solid var(--gray-200);
  display: none;
}
.filter-panel.active { display: block; }
.filter-panel h4 { font-family: var(--font-body); font-weight: 600; font-size: 0.875rem; margin-bottom: 12px; color: var(--gray-700); }
.filter-options { display: flex; flex-wrap: wrap; gap: 8px; }
.filter-chip {
  padding: 6px 14px; border-radius: var(--radius-full); border: 1px solid var(--gray-300);
  font-size: 0.8125rem; color: var(--gray-600); cursor: pointer; transition: all 0.15s;
}
.filter-chip:hover { border-color: var(--green); color: var(--green); }
.filter-chip.selected { background: var(--green-light); border-color: var(--green); color: var(--green); font-weight: 500; }

/* Search Suggestions */
.search-suggestions {
  position: absolute; top: 100%; left: 0; right: 52px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg); display: none; z-index: 10; overflow: hidden;
}
.search-suggestions.active { display: block; }
.suggestion-item {
  padding: 12px 16px; font-size: 0.9375rem; color: var(--gray-600);
  cursor: pointer; transition: background 0.15s;
}
.suggestion-item:hover { background: var(--green-light); color: var(--green); }

/* Store Results */
.store-results { flex: 1; overflow-y: auto; padding: 8px 0; }
.store-result-item {
  padding: 16px 20px; border-bottom: 1px solid var(--gray-100);
  cursor: pointer; transition: background 0.15s;
}
.store-result-item:hover { background: var(--green-light); }
.store-result-item .store-name { font-weight: 600; font-size: 0.9375rem; color: var(--gray-700); margin-bottom: 4px; }
.store-result-item .store-address { font-size: 0.8125rem; color: var(--gray-500); margin-bottom: 4px; }
.store-result-item .store-hours { font-size: 0.8125rem; color: var(--green); }
.store-result-item .store-features { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.store-feature-tag {
  padding: 2px 8px; border-radius: var(--radius-full); font-size: 0.6875rem;
  background: var(--gray-100); color: var(--gray-500);
}

/* Map */
.map-view { background: var(--gray-100); position: relative; }
.map-placeholder {
  width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
  flex-direction: column; gap: 16px; color: var(--gray-400);
}
.map-placeholder-icon { font-size: 4rem; }
.map-pin {
  position: absolute; width: 32px; height: 32px; background: var(--green);
  border-radius: 50% 50% 50% 0; transform: rotate(-45deg);
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-md); cursor: pointer; transition: transform 0.2s;
}
.map-pin:hover { transform: rotate(-45deg) scale(1.2); }
.map-pin span { transform: rotate(45deg); color: var(--white); font-weight: 700; font-size: 0.75rem; }

/* ==================== RESPONSIVE ==================== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .menu-layout { grid-template-columns: 220px 1fr; }
  .menu-main { padding: 24px 32px; }
  .tier-cards { grid-template-columns: 1fr; max-width: 480px; margin: 0 auto; }
  .locator-layout { grid-template-columns: 340px 1fr; }
}

@media (max-width: 768px) {
  :root { --header-height: 60px; }

  .nav-primary, .nav-account { display: none; }
  .mobile-menu-btn { display: flex; }

  .hero { padding: 48px 0; }
  .hero-inner { flex-direction: column; text-align: center; }
  .hero-text p { margin-left: auto; margin-right: auto; }
  .hero-image { width: 100%; }
  .hero-image-placeholder { max-width: 320px; }

  .section { padding: 48px 0; }
  .promo-grid { grid-template-columns: 1fr; }
  .seasonal-split { grid-template-columns: 1fr; }
  .seasonal-image { min-height: 240px; }

  .how-it-works { grid-template-columns: 1fr; gap: 24px; }
  .partnership-grid { grid-template-columns: 1fr; }

  .app-download { flex-direction: column; text-align: center; padding: 40px 28px; }
  .app-download p { margin-left: auto; margin-right: auto; }
  .app-buttons { justify-content: center; }

  .redemption-card { flex-direction: column; text-align: center; }

  .egift-info { grid-template-columns: 1fr; }

  .business-gifting { flex-direction: column; text-align: center; padding: 40px 28px; }
  .business-gifting p { margin-left: auto; margin-right: auto; }

  /* Menu mobile */
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar {
    position: static; height: auto; border-right: none; border-bottom: 1px solid var(--gray-200);
    padding: 16px; overflow-x: auto; overflow-y: hidden; white-space: nowrap;
  }
  .menu-sidebar h4 { display: inline; margin: 0 16px 0 0; }
  .menu-sidebar a { display: inline; padding: 6px 12px; margin-right: 4px; }
  .menu-main { padding: 24px; }
  .breadcrumb { padding: 12px 24px; }

  /* Store locator mobile */
  .locator-layout { grid-template-columns: 1fr; }
  .map-view { height: 300px; order: -1; }
  .locator-sidebar { border-right: none; border-top: 1px solid var(--gray-200); }

  /* Gift page */
  .gift-card { min-width: 160px; }
  .gift-card-img { width: 160px; height: 104px; }

  /* Footer accordion on mobile */
  .footer-grid { grid-template-columns: 1fr; }
  .footer-accordion-toggle { display: flex; }
  .footer-col h4 { display: none; }
  .footer-col-content { max-height: 500px; }
  .footer-col-content.collapsed { max-height: 0; }

  .cookie-banner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .tab-btn { padding: 10px 14px; font-size: 0.8125rem; }
  .carousel-nav button { width: 36px; height: 36px; }
  .gift-card { min-width: 140px; }
  .gift-card-img { width: 140px; height: 91px; }
}

/* Print */
@media print {
  .site-header, .site-footer, .cookie-banner { display: none; }
  .section { padding: 24px 0; }
}

/* ========================================
   GreenBean Coffee — Design System
   Colors: #00824A (green), #32462F (forest), #F3CEA1 (cream)
   Typography: Inter + DM Serif Display
   ======================================== */

@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --green: #00824A;
  --green-dark: #006838;
  --green-light: #e6f5ed;
  --forest: #32462F;
  --forest-light: #4a6345;
  --cream: #F3CEA1;
  --cream-light: #faf3e0;
  --cream-dark: #e8c278;
  --brown: #6F4E37;
  --brown-light: #8B6F47;
  --white: #FFFFFF;
  --off-white: #f9f7f4;
  --gray-50: #fafafa;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'DM Serif Display', Georgia, serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.12);
  --shadow-xl: 0 16px 40px rgba(0,0,0,0.16);
  --max-width: 1280px;
  --header-height: 72px;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body { font-family: var(--font-body); color: var(--gray-800); line-height: 1.6; background: var(--white); }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
input, select, textarea { font-family: inherit; font-size: inherit; }

/* Typography */
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: 400; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.125rem; }
p { max-width: 65ch; }

/* Utility Classes */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full); font-weight: 600;
  font-size: 0.9375rem; transition: all 0.2s ease; white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-secondary { background: var(--white); color: var(--green); border: 1.5px solid var(--green); }
.btn-secondary:hover { background: var(--green-light); }
.btn-cream { background: var(--cream); color: var(--forest); }
.btn-cream:hover { background: var(--cream-dark); }
.btn-forest { background: var(--forest); color: var(--cream); }
.btn-forest:hover { background: var(--forest-light); }
.btn-sm { padding: 8px 20px; font-size: 0.875rem; }
.btn-lg { padding: 16px 36px; font-size: 1rem; }

/* ==================== HEADER ==================== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--white); border-bottom: 1px solid var(--gray-200);
  height: var(--header-height);
}
.header-inner {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; justify-content: space-between; height: 100%;
}
.logo { display: flex; align-items: center; gap: 8px; font-family: var(--font-heading); font-size: 1.5rem; color: var(--green); }
.logo-icon { width: 36px; height: 36px; background: var(--green); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--white); font-size: 1.125rem; }
.nav-primary { display: flex; align-items: center; gap: 32px; }
.nav-primary a { font-weight: 500; color: var(--gray-700); transition: color 0.2s; font-size: 0.9375rem; }
.nav-primary a:hover { color: var(--green); }
.nav-account { display: flex; align-items: center; gap: 16px; }
.nav-account a { font-size: 0.875rem; font-weight: 500; color: var(--gray-600); }
.nav-account a:hover { color: var(--green); }
.nav-account .btn { font-size: 0.875rem; padding: 8px 20px; }
.mobile-menu-btn { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; }
.hamburger { width: 24px; height: 2px; background: var(--gray-700); position: relative; transition: all 0.3s; }
.hamburger::before, .hamburger::after { content: ''; position: absolute; width: 24px; height: 2px; background: var(--gray-700); transition: all 0.3s; }
.hamburger::before { top: -7px; }
.hamburger::after { top: 7px; }
.mobile-nav { display: none; position: fixed; top: var(--header-height); left: 0; right: 0; bottom: 0; background: var(--white); z-index: 99; padding: 24px; }
.mobile-nav.active { display: block; }
.mobile-nav a { display: block; padding: 16px 0; font-size: 1.25rem; font-weight: 500; color: var(--gray-700); border-bottom: 1px solid var(--gray-200); }

/* ==================== FOOTER ==================== */
.site-footer { background: var(--forest); color: var(--cream-light); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px; margin-bottom: 48px; }
.footer-col h4 { color: var(--white); font-family: var(--font-body); font-weight: 700; font-size: 0.9375rem; margin-bottom: 16px; cursor: default; }
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a { color: var(--cream-light); font-size: 0.875rem; opacity: 0.85; transition: opacity 0.2s; }
.footer-col ul li a:hover { opacity: 1; }
.footer-bottom { border-top: 1px solid rgba(243,206,161,0.2); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
.footer-bottom p { font-size: 0.8125rem; opacity: 0.7; }
.footer-social { display: flex; gap: 16px; }
.footer-social a { width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; font-size: 0.875rem; transition: background 0.2s; }
.footer-social a:hover { background: rgba(255,255,255,0.2); }

/* Footer accordion (mobile) */
.footer-accordion-toggle { display: none; width: 100%; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid rgba(243,206,161,0.15); }
.footer-accordion-toggle h4 { margin-bottom: 0; }
.footer-accordion-toggle .chevron { transition: transform 0.3s; font-size: 0.75rem; }
.footer-accordion-toggle.active .chevron { transform: rotate(180deg); }
.footer-col-content { overflow: hidden; transition: max-height 0.3s ease; }
.footer-col-content.collapsed { max-height: 0 !important; }

/* ==================== COOKIE BANNER ==================== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--forest); color: var(--cream-light); padding: 20px 24px;
  display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
}
.cookie-banner.hidden { display: none; }
.cookie-banner p { font-size: 0.875rem; max-width: 600px; }
.cookie-banner .btn { font-size: 0.8125rem; padding: 8px 20px; }

/* ==================== HERO ==================== */
.hero {
  background: linear-gradient(135deg, var(--green-light) 0%, var(--cream-light) 100%);
  padding: 80px 0; position: relative; overflow: hidden;
}
.hero-inner { display: flex; align-items: center; gap: 48px; }
.hero-text { flex: 1; }
.hero-text h1 { margin-bottom: 16px; color: var(--forest); }
.hero-text p { font-size: 1.125rem; color: var(--gray-600); margin-bottom: 32px; max-width: 480px; }
.hero-image { flex: 1; display: flex; justify-content: center; }
.hero-image-placeholder {
  width: 100%; max-width: 480px; aspect-ratio: 1; border-radius: var(--radius-xl);
  background: linear-gradient(145deg, var(--cream) 0%, var(--cream-dark) 100%);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.5rem; color: var(--brown);
  box-shadow: var(--shadow-lg);
}

/* ==================== SECTION STYLES ==================== */
.section { padding: 80px 0; }
.section-cream { background: var(--cream-light); }
.section-green { background: var(--green-light); }
.section-forest { background: var(--forest); color: var(--cream-light); }
.section-forest h2, .section-forest h3 { color: var(--white); }

.section-header { margin-bottom: 48px; }
.section-header h2 { margin-bottom: 12px; }
.section-header p { font-size: 1.0625rem; color: var(--gray-500); max-width: 560px; }

/* ==================== PROMO CARDS ==================== */
.promo-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.promo-card {
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white); box-shadow: var(--shadow-md);
  transition: transform 0.2s, box-shadow 0.2s;
}
.promo-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.promo-card-image {
  height: 240px; display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.25rem; color: var(--brown);
}
.promo-card-body { padding: 28px; }
.promo-card-body h3 { margin-bottom: 8px; color: var(--forest); }
.promo-card-body p { font-size: 0.9375rem; color: var(--gray-500); margin-bottom: 20px; }

/* ==================== SEASONAL HIGHLIGHTS ==================== */
.seasonal-split { display: grid; grid-template-columns: 1fr 1fr; gap: 0; min-height: 480px; border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-lg); }
.seasonal-image {
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.5rem; color: var(--brown);
}
.seasonal-content { padding: 48px; display: flex; flex-direction: column; justify-content: center; }
.seasonal-content h2 { margin-bottom: 16px; color: var(--forest); }
.seasonal-content p { font-size: 1.0625rem; color: var(--gray-500); margin-bottom: 28px; }

/* ==================== MENU PAGE ==================== */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 0; min-height: calc(100vh - var(--header-height)); }
.menu-sidebar {
  background: var(--off-white); border-right: 1px solid var(--gray-200);
  padding: 32px 24px; position: sticky; top: var(--header-height); height: calc(100vh - var(--header-height)); overflow-y: auto;
}
.menu-sidebar h4 { font-family: var(--font-body); font-weight: 700; font-size: 0.8125rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 12px; margin-top: 24px; }
.menu-sidebar h4:first-child { margin-top: 0; }
.menu-sidebar a { display: block; padding: 8px 12px; border-radius: var(--radius-sm); font-size: 0.9375rem; color: var(--gray-600); transition: all 0.15s; margin-bottom: 2px; }
.menu-sidebar a:hover { background: var(--green-light); color: var(--green); }
.menu-sidebar a.active { background: var(--green); color: var(--white); font-weight: 500; }
.menu-main { padding: 32px 48px; }
.menu-section { margin-bottom: 56px; }
.menu-section h2 { margin-bottom: 8px; color: var(--forest); }
.menu-section > p { color: var(--gray-500); margin-bottom: 28px; }
.menu-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 20px; }
.menu-item { text-align: center; }
.menu-item-img {
  width: 100%; aspect-ratio: 1; border-radius: var(--radius-md);
  background: var(--cream-light); display: flex; align-items: center; justify-content: center;
  font-size: 2rem; margin-bottom: 12px; transition: transform 0.2s;
}
.menu-item-img:hover { transform: scale(1.05); }
.menu-item h4 { font-family: var(--font-body); font-weight: 600; font-size: 0.9375rem; color: var(--gray-700); }

/* Breadcrumb */
.breadcrumb { padding: 16px 48px; background: var(--off-white); border-bottom: 1px solid var(--gray-200); }
.breadcrumb-inner { display: flex; align-items: center; gap: 8px; font-size: 0.875rem; color: var(--gray-500); }
.breadcrumb-inner a { color: var(--green); }
.breadcrumb-inner .sep { color: var(--gray-300); }

/* ==================== REWARDS PAGE ==================== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green) 0%, #00a85e 100%);
  padding: 80px 0; color: var(--white); text-align: center;
}
.rewards-hero h1 { margin-bottom: 16px; }
.rewards-hero p { font-size: 1.125rem; opacity: 0.9; margin: 0 auto 32px; max-width: 520px; }

.how-it-works { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; text-align: center; }
.how-step { padding: 32px; }
.how-step-number {
  width: 56px; height: 56px; border-radius: 50%; background: var(--green);
  color: var(--white); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1.25rem; margin: 0 auto 20px;
}
.how-step h3 { margin-bottom: 8px; color: var(--forest); }
.how-step p { font-size: 0.9375rem; color: var(--gray-500); }

/* Status Tiers */
.tier-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tier-card {
  border-radius: var(--radius-lg); padding: 36px 28px; position: relative; overflow: hidden;
  border: 2px solid var(--gray-200); transition: border-color 0.2s, box-shadow 0.2s;
}
.tier-card:hover { border-color: var(--green); box-shadow: var(--shadow-md); }
.tier-card.gold-card { border-color: var(--cream-dark); }
.tier-card.gold-card:hover { border-color: #d4a843; }
.tier-card.reserve-card { border-color: var(--forest); background: var(--forest); color: var(--cream-light); }
.tier-card.reserve-card:hover { box-shadow: var(--shadow-lg); }
.tier-badge {
  display: inline-block; padding: 4px 16px; border-radius: var(--radius-full);
  font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
  margin-bottom: 16px;
}
.tier-badge.green-badge { background: var(--green-light); color: var(--green); }
.tier-badge.gold-badge { background: var(--cream); color: #8B6914; }
.tier-badge.reserve-badge { background: rgba(255,255,255,0.15); color: var(--cream); }
.tier-card h3 { margin-bottom: 4px; }
.tier-card .tier-threshold { font-size: 0.875rem; color: var(--gray-400); margin-bottom: 20px; }
.tier-card.reserve-card .tier-threshold { color: rgba(243,206,161,0.6); }
.tier-card ul { font-size: 0.9375rem; }
.tier-card ul li { padding: 6px 0; display: flex; align-items: flex-start; gap: 8px; }
.tier-card ul li::before { content: '★'; color: var(--cream-dark); flex-shrink: 0; }
.tier-card.reserve-card ul li::before { color: var(--cream); }

/* Redemption Tabs */
.redemption-tabs { margin-top: 48px; }
.tab-list {
  display: flex; gap: 4px; border-bottom: 2px solid var(--gray-200);
  overflow-x: auto; -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.tab-list::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 14px 20px; font-weight: 600; font-size: 0.9375rem;
  color: var(--gray-500); border-bottom: 3px solid transparent;
  transition: all 0.2s; white-space: nowrap; margin-bottom: -2px;
}
.tab-btn:hover { color: var(--green); }
.tab-btn.active { color: var(--green); border-bottom-color: var(--green); }
.tab-panel { display: none; padding: 32px 0; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.redemption-card {
  display: flex; align-items: center; gap: 32px;
  padding: 32px; background: var(--white); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm); border: 1px solid var(--gray-200);
}
.redemption-icon {
  width: 120px; height: 120px; border-radius: var(--radius-md);
  background: var(--cream-light); display: flex; align-items: center; justify-content: center;
  font-size: 3rem; flex-shrink: 0;
}
.redemption-info h3 { margin-bottom: 4px; color: var(--forest); }
.redemption-info .reward-desc { font-size: 1rem; color: var(--gray-600); margin-bottom: 4px; }
.redemption-info .reward-value { font-size: 0.875rem; color: var(--green); font-weight: 600; }

/* Partnerships */
.partnership-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.partnership-card {
  padding: 36px; border-radius: var(--radius-lg); border: 1px solid var(--gray-200);
  display: flex; align-items: center; gap: 24px; transition: box-shadow 0.2s;
}
.partnership-card:hover { box-shadow: var(--shadow-md); }
.partner-logo {
  width: 64px; height: 64px; border-radius: var(--radius-md);
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1.5rem; color: var(--gray-600); flex-shrink: 0;
}
.partnership-card h3 { font-size: 1.125rem; margin-bottom: 4px; color: var(--forest); }
.partnership-card p { font-size: 0.9375rem; color: var(--gray-500); }

/* App Download */
.app-download {
  background: linear-gradient(135deg, var(--green) 0%, #00a85e 100%);
  border-radius: var(--radius-xl); padding: 56px; display: flex; align-items: center;
  justify-content: space-between; gap: 40px; color: var(--white);
}
.app-download h2 { margin-bottom: 12px; }
.app-download p { opacity: 0.9; font-size: 1.0625rem; max-width: 480px; }
.app-buttons { display: flex; gap: 12px; }
.app-btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 24px; background: var(--white); color: var(--green);
  border-radius: var(--radius-sm); font-weight: 600; font-size: 0.9375rem;
  transition: transform 0.2s;
}
.app-btn:hover { transform: translateY(-2px); }

/* ==================== GIFT PAGE ==================== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream-light) 0%, #fde8c8 100%);
  padding: 80px 0; text-align: center;
}
.gift-hero h1 { margin-bottom: 16px; color: var(--forest); }
.gift-hero p { font-size: 1.125rem; color: var(--gray-500); max-width: 560px; margin: 0 auto 32px; }

/* Carousel */
.carousel-section { margin-bottom: 56px; }
.carousel-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
.carousel-header h3 { color: var(--forest); }
.carousel-nav { display: flex; gap: 8px; }
.carousel-nav button {
  width: 40px; height: 40px; border-radius: 50%; border: 1.5px solid var(--gray-300);
  display: flex; align-items: center; justify-content: center; font-size: 1.125rem;
  color: var(--gray-600); transition: all 0.2s; background: var(--white);
}
.carousel-nav button:hover { border-color: var(--green); color: var(--green); background: var(--green-light); }

.carousel-track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex; gap: 16px; transition: transform 0.4s cubic-bezier(0.25, 0.1, 0.25, 1);
}
.gift-card {
  min-width: 200px; flex-shrink: 0; cursor: pointer;
  transition: transform 0.2s;
}
.gift-card:hover { transform: translateY(-4px); }
.gift-card-img {
  width: 200px; height: 130px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.8125rem; font-weight: 600; color: var(--white);
  margin-bottom: 8px; box-shadow: var(--shadow-md);
}
.gift-card-name { font-size: 0.8125rem; color: var(--gray-600); text-align: center; }

/* Category section */
.category-section { margin-bottom: 48px; }

/* Business gifting */
.business-gifting {
  display: flex; align-items: center; gap: 48px;
  padding: 56px; background: var(--forest); border-radius: var(--radius-xl); color: var(--cream-light);
}
.business-gifting h2 { color: var(--white); margin-bottom: 12px; }
.business-gifting p { opacity: 0.85; font-size: 1.0625rem; margin-bottom: 24px; max-width: 520px; }

/* eGift Info */
.egift-info { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start; }
.egift-text h3 { margin-bottom: 16px; color: var(--forest); }
.egift-text p { font-size: 0.9375rem; color: var(--gray-500); margin-bottom: 12px; }
.egift-links { display: flex; flex-wrap: wrap; gap: 16px; }
.egift-links a { color: var(--green); font-weight: 500; font-size: 0.9375rem; }
.egift-links a:hover { text-decoration: underline; }

/* FAQ */
.faq-list { max-width: 720px; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  width: 100%; padding: 20px 0; display: flex; justify-content: space-between;
  align-items: center; font-size: 1rem; font-weight: 500; color: var(--gray-700);
  text-align: left;
}
.faq-question .faq-icon { transition: transform 0.3s; font-size: 1.25rem; color: var(--gray-400); }
.faq-question.active .faq-icon { transform: rotate(45deg); }
.faq-answer { padding: 0 0 20px; font-size: 0.9375rem; color: var(--gray-500); display: none; }
.faq-answer.active { display: block; }

/* ==================== STORE LOCATOR ==================== */
.locator-layout { display: grid; grid-template-columns: 400px 1fr; min-height: calc(100vh - var(--header-height)); }
.locator-sidebar { background: var(--white); border-right: 1px solid var(--gray-200); display: flex; flex-direction: column; }

.search-controls { padding: 20px; border-bottom: 1px solid var(--gray-200); }
.search-input-wrap { display: flex; gap: 8px; margin-bottom: 12px; }
.search-input {
  flex: 1; padding: 12px 16px; border: 1.5px solid var(--gray-300); border-radius: var(--radius-full);
  font-size: 0.9375rem; outline: none; transition: border-color 0.2s;
}
.search-input:focus { border-color: var(--green); }
.search-input::placeholder { color: var(--gray-400); }
.search-btn {
  width: 44px; height: 44px; border-radius: 50%; background: var(--green);
  color: var(--white); display: flex; align-items: center; justify-content: center;
  font-size: 1.125rem; transition: background 0.2s;
}
.search-btn:hover { background: var(--green-dark); }

.search-filters { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.filter-btn {
  padding: 8px 16px; border-radius: var(--radius-full); border: 1.5px solid var(--gray-300);
  font-size: 0.8125rem; font-weight: 500; color: var(--gray-600); transition: all 0.2s;
  display: flex; align-items: center; gap: 4px;
}
.filter-btn:hover { border-color: var(--green); color: var(--green); }
.filter-btn.active { background: var(--green); color: var(--white); border-color: var(--green); }

.order-type-toggle {
  display: flex; background: var(--gray-100); border-radius: var(--radius-full); padding: 3px;
}
.order-type-btn {
  flex: 1; padding: 8px 20px; border-radius: var(--radius-full); font-size: 0.875rem;
  font-weight: 500; color: var(--gray-500); text-align: center; transition: all 0.2s;
}
.order-type-btn.active { background: var(--white); color: var(--green); box-shadow: var(--shadow-sm); }

.filter-panel {
  padding: 16px 20px; background: var(--off-white); border-bottom: 1px solid var(--gray-200);
  display: none;
}
.filter-panel.active { display: block; }
.filter-panel h4 { font-family: var(--font-body); font-weight: 600; font-size: 0.875rem; margin-bottom: 12px; color: var(--gray-700); }
.filter-options { display: flex; flex-wrap: wrap; gap: 8px; }
.filter-chip {
  padding: 6px 14px; border-radius: var(--radius-full); border: 1px solid var(--gray-300);
  font-size: 0.8125rem; color: var(--gray-600); cursor: pointer; transition: all 0.15s;
}
.filter-chip:hover { border-color: var(--green); color: var(--green); }
.filter-chip.selected { background: var(--green-light); border-color: var(--green); color: var(--green); font-weight: 500; }

/* Search Suggestions */
.search-suggestions {
  position: absolute; top: 100%; left: 0; right: 52px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg); display: none; z-index: 10; overflow: hidden;
}
.search-suggestions.active { display: block; }
.suggestion-item {
  padding: 12px 16px; font-size: 0.9375rem; color: var(--gray-600);
  cursor: pointer; transition: background 0.15s;
}
.suggestion-item:hover { background: var(--green-light); color: var(--green); }

/* Store Results */
.store-results { flex: 1; overflow-y: auto; padding: 8px 0; }
.store-result-item {
  padding: 16px 20px; border-bottom: 1px solid var(--gray-100);
  cursor: pointer; transition: background 0.15s;
}
.store-result-item:hover { background: var(--green-light); }
.store-result-item .store-name { font-weight: 600; font-size: 0.9375rem; color: var(--gray-700); margin-bottom: 4px; }
.store-result-item .store-address { font-size: 0.8125rem; color: var(--gray-500); margin-bottom: 4px; }
.store-result-item .store-hours { font-size: 0.8125rem; color: var(--green); }
.store-result-item .store-features { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.store-feature-tag {
  padding: 2px 8px; border-radius: var(--radius-full); font-size: 0.6875rem;
  background: var(--gray-100); color: var(--gray-500);
}

/* Map */
.map-view { background: var(--gray-100); position: relative; }
.map-placeholder {
  width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
  flex-direction: column; gap: 16px; color: var(--gray-400);
}
.map-placeholder-icon { font-size: 4rem; }
.map-pin {
  position: absolute; width: 32px; height: 32px; background: var(--green);
  border-radius: 50% 50% 50% 0; transform: rotate(-45deg);
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-md); cursor: pointer; transition: transform 0.2s;
}
.map-pin:hover { transform: rotate(-45deg) scale(1.2); }
.map-pin span { transform: rotate(45deg); color: var(--white); font-weight: 700; font-size: 0.75rem; }

/* ==================== RESPONSIVE ==================== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .menu-layout { grid-template-columns: 220px 1fr; }
  .menu-main { padding: 24px 32px; }
  .tier-cards { grid-template-columns: 1fr; max-width: 480px; margin: 0 auto; }
  .locator-layout { grid-template-columns: 340px 1fr; }
}

@media (max-width: 768px) {
  :root { --header-height: 60px; }

  .nav-primary, .nav-account { display: none; }
  .mobile-menu-btn { display: flex; }

  .hero { padding: 48px 0; }
  .hero-inner { flex-direction: column; text-align: center; }
  .hero-text p { margin-left: auto; margin-right: auto; }
  .hero-image { width: 100%; }
  .hero-image-placeholder { max-width: 320px; }

  .section { padding: 48px 0; }
  .promo-grid { grid-template-columns: 1fr; }
  .seasonal-split { grid-template-columns: 1fr; }
  .seasonal-image { min-height: 240px; }

  .how-it-works { grid-template-columns: 1fr; gap: 24px; }
  .partnership-grid { grid-template-columns: 1fr; }

  .app-download { flex-direction: column; text-align: center; padding: 40px 28px; }
  .app-download p { margin-left: auto; margin-right: auto; }
  .app-buttons { justify-content: center; }

  .redemption-card { flex-direction: column; text-align: center; }

  .egift-info { grid-template-columns: 1fr; }

  .business-gifting { flex-direction: column; text-align: center; padding: 40px 28px; }
  .business-gifting p { margin-left: auto; margin-right: auto; }

  /* Menu mobile */
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar {
    position: static; height: auto; border-right: none; border-bottom: 1px solid var(--gray-200);
    padding: 16px; overflow-x: auto; overflow-y: hidden; white-space: nowrap;
  }
  .menu-sidebar h4 { display: inline; margin: 0 16px 0 0; }
  .menu-sidebar a { display: inline; padding: 6px 12px; margin-right: 4px; }
  .menu-main { padding: 24px; }
  .breadcrumb { padding: 12px 24px; }

  /* Store locator mobile */
  .locator-layout { grid-template-columns: 1fr; }
  .map-view { height: 300px; order: -1; }
  .locator-sidebar { border-right: none; border-top: 1px solid var(--gray-200); }

  /* Gift page */
  .gift-card { min-width: 160px; }
  .gift-card-img { width: 160px; height: 104px; }

  /* Footer accordion on mobile */
  .footer-grid { grid-template-columns: 1fr; }
  .footer-accordion-toggle { display: flex; }
  .footer-col h4 { display: none; }
  .footer-col-content { max-height: 500px; }
  .footer-col-content.collapsed { max-height: 0; }

  .cookie-banner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .tab-btn { padding: 10px 14px; font-size: 0.8125rem; }
  .carousel-nav button { width: 36px; height: 36px; }
  .gift-card { min-width: 140px; }
  .gift-card-img { width: 140px; height: 91px; }
}

/* Print */
@media print {
  .site-header, .site-footer, .cookie-banner { display: none; }
  .section { padding: 24px 0; }
}

raw_arguments.content:
/* ========================================
   GreenBean Coffee — Design System
   Colors: #00824A (green), #32462F (forest), #F3CEA1 (cream)
   Typography: Inter + DM Serif Display
   ======================================== */

@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --green: #00824A;
  --green-dark: #006838;
  --green-light: #e6f5ed;
  --forest: #32462F;
  --forest-light: #4a6345;
  --cream: #F3CEA1;
  --cream-light: #faf3e0;
  --cream-dark: #e8c278;
  --brown: #6F4E37;
  --brown-light: #8B6F47;
  --white: #FFFFFF;
  --off-white: #f9f7f4;
  --gray-50: #fafafa;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'DM Serif Display', Georgia, serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.12);
  --shadow-xl: 0 16px 40px rgba(0,0,0,0.16);
  --max-width: 1280px;
  --header-height: 72px;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body { font-family: var(--font-body); color: var(--gray-800); line-height: 1.6; background: var(--white); }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
input, select, textarea { font-family: inherit; font-size: inherit; }

/* Typography */
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: 400; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.125rem; }
p { max-width: 65ch; }

/* Utility Classes */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full); font-weight: 600;
  font-size: 0.9375rem; transition: all 0.2s ease; white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-secondary { background: var(--white); color: var(--green); border: 1.5px solid var(--green); }
.btn-secondary:hover { background: var(--green-light); }
.btn-cream { background: var(--cream); color: var(--forest); }
.btn-cream:hover { background: var(--cream-dark); }
.btn-forest { background: var(--forest); color: var(--cream); }
.btn-forest:hover { background: var(--forest-light); }
.btn-sm { padding: 8px 20px; font-size: 0.875rem; }
.btn-lg { padding: 16px 36px; font-size: 1rem; }

/* ==================== HEADER ==================== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--white); border-bottom: 1px solid var(--gray-200);
  height: var(--header-height);
}
.header-inner {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; justify-content: space-between; height: 100%;
}
.logo { display: flex; align-items: center; gap: 8px; font-family: var(--font-heading); font-size: 1.5rem; color: var(--green); }
.logo-icon { width: 36px; height: 36px; background: var(--green); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--white); font-size: 1.125rem; }
.nav-primary { display: flex; align-items: center; gap: 32px; }
.nav-primary a { font-weight: 500; color: var(--gray-700); transition: color 0.2s; font-size: 0.9375rem; }
.nav-primary a:hover { color: var(--green); }
.nav-account { display: flex; align-items: center; gap: 16px; }
.nav-account a { font-size: 0.875rem; font-weight: 500; color: var(--gray-600); }
.nav-account a:hover { color: var(--green); }
.nav-account .btn { font-size: 0.875rem; padding: 8px 20px; }
.mobile-menu-btn { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; }
.hamburger { width: 24px; height: 2px; background: var(--gray-700); position: relative; transition: all 0.3s; }
.hamburger::before, .hamburger::after { content: ''; position: absolute; width: 24px; height: 2px; background: var(--gray-700); transition: all 0.3s; }
.hamburger::before { top: -7px; }
.hamburger::after { top: 7px; }
.mobile-nav { display: none; position: fixed; top: var(--header-height); left: 0; right: 0; bottom: 0; background: var(--white); z-index: 99; padding: 24px; }
.mobile-nav.active { display: block; }
.mobile-nav a { display: block; padding: 16px 0; font-size: 1.25rem; font-weight: 500; color: var(--gray-700); border-bottom: 1px solid var(--gray-200); }

/* ==================== FOOTER ==================== */
.site-footer { background: var(--forest); color: var(--cream-light); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px; margin-bottom: 48px; }
.footer-col h4 { color: var(--white); font-family: var(--font-body); font-weight: 700; font-size: 0.9375rem; margin-bottom: 16px; cursor: default; }
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a { color: var(--cream-light); font-size: 0.875rem; opacity: 0.85; transition: opacity 0.2s; }
.footer-col ul li a:hover { opacity: 1; }
.footer-bottom { border-top: 1px solid rgba(243,206,161,0.2); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
.footer-bottom p { font-size: 0.8125rem; opacity: 0.7; }
.footer-social { display: flex; gap: 16px; }
.footer-social a { width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; font-size: 0.875rem; transition: background 0.2s; }
.footer-social a:hover { background: rgba(255,255,255,0.2); }

/* Footer accordion (mobile) */
.footer-accordion-toggle { display: none; width: 100%; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid rgba(243,206,161,0.15); }
.footer-accordion-toggle h4 { margin-bottom: 0; }
.footer-accordion-toggle .chevron { transition: transform 0.3s; font-size: 0.75rem; }
.footer-accordion-toggle.active .chevron { transform: rotate(180deg); }
.footer-col-content { overflow: hidden; transition: max-height 0.3s ease; }
.footer-col-content.collapsed { max-height: 0 !important; }

/* ==================== COOKIE BANNER ==================== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--forest); color: var(--cream-light); padding: 20px 24px;
  display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
}
.cookie-banner.hidden { display: none; }
.cookie-banner p { font-size: 0.875rem; max-width: 600px; }
.cookie-banner .btn { font-size: 0.8125rem; padding: 8px 20px; }

/* ==================== HERO ==================== */
.hero {
  background: linear-gradient(135deg, var(--green-light) 0%, var(--cream-light) 100%);
  padding: 80px 0; position: relative; overflow: hidden;
}
.hero-inner { display: flex; align-items: center; gap: 48px; }
.hero-text { flex: 1; }
.hero-text h1 { margin-bottom: 16px; color: var(--forest); }
.hero-text p { font-size: 1.125rem; color: var(--gray-600); margin-bottom: 32px; max-width: 480px; }
.hero-image { flex: 1; display: flex; justify-content: center; }
.hero-image-placeholder {
  width: 100%; max-width: 480px; aspect-ratio: 1; border-radius: var(--radius-xl);
  background: linear-gradient(145deg, var(--cream) 0%, var(--cream-dark) 100%);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.5rem; color: var(--brown);
  box-shadow: var(--shadow-lg);
}

/* ==================== SECTION STYLES ==================== */
.section { padding: 80px 0; }
.section-cream { background: var(--cream-light); }
.section-green { background: var(--green-light); }
.section-forest { background: var(--forest); color: var(--cream-light); }
.section-forest h2, .section-forest h3 { color: var(--white); }

.section-header { margin-bottom: 48px; }
.section-header h2 { margin-bottom: 12px; }
.section-header p { font-size: 1.0625rem; color: var(--gray-500); max-width: 560px; }

/* ==================== PROMO CARDS ==================== */
.promo-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.promo-card {
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white); box-shadow: var(--shadow-md);
  transition: transform 0.2s, box-shadow 0.2s;
}
.promo-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.promo-card-image {
  height: 240px; display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.25rem; color: var(--brown);
}
.promo-card-body { padding: 28px; }
.promo-card-body h3 { margin-bottom: 8px; color: var(--forest); }
.promo-card-body p { font-size: 0.9375rem; color: var(--gray-500); margin-bottom: 20px; }

/* ==================== SEASONAL HIGHLIGHTS ==================== */
.seasonal-split { display: grid; grid-template-columns: 1fr 1fr; gap: 0; min-height: 480px; border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-lg); }
.seasonal-image {
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-size: 1.5rem; color: var(--brown);
}
.seasonal-content { padding: 48px; display: flex; flex-direction: column; justify-content: center; }
.seasonal-content h2 { margin-bottom: 16px; color: var(--forest); }
.seasonal-content p { font-size: 1.0625rem; color: var(--gray-500); margin-bottom: 28px; }

/* ==================== MENU PAGE ==================== */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 0; min-height: calc(100vh - var(--header-height)); }
.menu-sidebar {
  background: var(--off-white); border-right: 1px solid var(--gray-200);
  padding: 32px 24px; position: sticky; top: var(--header-height); height: calc(100vh - var(--header-height)); overflow-y: auto;
}
.menu-sidebar h4 { font-family: var(--font-body); font-weight: 700; font-size: 0.8125rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 12px; margin-top: 24px; }
.menu-sidebar h4:first-child { margin-top: 0; }
.menu-sidebar a { display: block; padding: 8px 12px; border-radius: var(--radius-sm); font-size: 0.9375rem; color: var(--gray-600); transition: all 0.15s; margin-bottom: 2px; }
.menu-sidebar a:hover { background: var(--green-light); color: var(--green); }
.menu-sidebar a.active { background: var(--green); color: var(--white); font-weight: 500; }
.menu-main { padding: 32px 48px; }
.menu-section { margin-bottom: 56px; }
.menu-section h2 { margin-bottom: 8px; color: var(--forest); }
.menu-section > p { color: var(--gray-500); margin-bottom: 28px; }
.menu-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 20px; }
.menu-item { text-align: center; }
.menu-item-img {
  width: 100%; aspect-ratio: 1; border-radius: var(--radius-md);
  background: var(--cream-light); display: flex; align-items: center; justify-content: center;
  font-size: 2rem; margin-bottom: 12px; transition: transform 0.2s;
}
.menu-item-img:hover { transform: scale(1.05); }
.menu-item h4 { font-family: var(--font-body); font-weight: 600; font-size: 0.9375rem; color: var(--gray-700); }

/* Breadcrumb */
.breadcrumb { padding: 16px 48px; background: var(--off-white); border-bottom: 1px solid var(--gray-200); }
.breadcrumb-inner { display: flex; align-items: center; gap: 8px; font-size: 0.875rem; color: var(--gray-500); }
.breadcrumb-inner a { color: var(--green); }
.breadcrumb-inner .sep { color: var(--gray-300); }

/* ==================== REWARDS PAGE ==================== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green) 0%, #00a85e 100%);
  padding: 80px 0; color: var(--white); text-align: center;
}
.rewards-hero h1 { margin-bottom: 16px; }
.rewards-hero p { font-size: 1.125rem; opacity: 0.9; margin: 0 auto 32px; max-width: 520px; }

.how-it-works { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; text-align: center; }
.how-step { padding: 32px; }
.how-step-number {
  width: 56px; height: 56px; border-radius: 50%; background: var(--green);
  color: var(--white); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1.25rem; margin: 0 auto 20px;
}
.how-step h3 { margin-bottom: 8px; color: var(--forest); }
.how-step p { font-size: 0.9375rem; color: var(--gray-500); }

/* Status Tiers */
.tier-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tier-card {
  border-radius: var(--radius-lg); padding: 36px 28px; position: relative; overflow: hidden;
  border: 2px solid var(--gray-200); transition: border-color 0.2s, box-shadow 0.2s;
}
.tier-card:hover { border-color: var(--green); box-shadow: var(--shadow-md); }
.tier-card.gold-card { border-color: var(--cream-dark); }
.tier-card.gold-card:hover { border-color: #d4a843; }
.tier-card.reserve-card { border-color: var(--forest); background: var(--forest); color: var(--cream-light); }
.tier-card.reserve-card:hover { box-shadow: var(--shadow-lg); }
.tier-badge {
  display: inline-block; padding: 4px 16px; border-radius: var(--radius-full);
  font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
  margin-bottom: 16px;
}
.tier-badge.green-badge { background: var(--green-light); color: var(--green); }
.tier-badge.gold-badge { background: var(--cream); color: #8B6914; }
.tier-badge.reserve-badge { background: rgba(255,255,255,0.15); color: var(--cream); }
.tier-card h3 { margin-bottom: 4px; }
.tier-card .tier-threshold { font-size: 0.875rem; color: var(--gray-400); margin-bottom: 20px; }
.tier-card.reserve-card .tier-threshold { color: rgba(243,206,161,0.6); }
.tier-card ul { font-size: 0.9375rem; }
.tier-card ul li { padding: 6px 0; display: flex; align-items: flex-start; gap: 8px; }
.tier-card ul li::before { content: '★'; color: var(--cream-dark); flex-shrink: 0; }
.tier-card.reserve-card ul li::before { color: var(--cream); }

/* Redemption Tabs */
.redemption-tabs { margin-top: 48px; }
.tab-list {
  display: flex; gap: 4px; border-bottom: 2px solid var(--gray-200);
  overflow-x: auto; -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.tab-list::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 14px 20px; font-weight: 600; font-size: 0.9375rem;
  color: var(--gray-500); border-bottom: 3px solid transparent;
  transition: all 0.2s; white-space: nowrap; margin-bottom: -2px;
}
.tab-btn:hover { color: var(--green); }
.tab-btn.active { color: var(--green); border-bottom-color: var(--green); }
.tab-panel { display: none; padding: 32px 0; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.redemption-card {
  display: flex; align-items: center; gap: 32px;
  padding: 32px; background: var(--white); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm); border: 1px solid var(--gray-200);
}
.redemption-icon {
  width: 120px; height: 120px; border-radius: var(--radius-md);
  background: var(--cream-light); display: flex; align-items: center; justify-content: center;
  font-size: 3rem; flex-shrink: 0;
}
.redemption-info h3 { margin-bottom: 4px; color: var(--forest); }
.redemption-info .reward-desc { font-size: 1rem; color: var(--gray-600); margin-bottom: 4px; }
.redemption-info .reward-value { font-size: 0.875rem; color: var(--green); font-weight: 600; }

/* Partnerships */
.partnership-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.partnership-card {
  padding: 36px; border-radius: var(--radius-lg); border: 1px solid var(--gray-200);
  display: flex; align-items: center; gap: 24px; transition: box-shadow 0.2s;
}
.partnership-card:hover { box-shadow: var(--shadow-md); }
.partner-logo {
  width: 64px; height: 64px; border-radius: var(--radius-md);
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1.5rem; color: var(--gray-600); flex-shrink: 0;
}
.partnership-card h3 { font-size: 1.125rem; margin-bottom: 4px; color: var(--forest); }
.partnership-card p { font-size: 0.9375rem; color: var(--gray-500); }

/* App Download */
.app-download {
  background: linear-gradient(135deg, var(--green) 0%, #00a85e 100%);
  border-radius: var(--radius-xl); padding: 56px; display: flex; align-items: center;
  justify-content: space-between; gap: 40px; color: var(--white);
}
.app-download h2 { margin-bottom: 12px; }
.app-download p { opacity: 0.9; font-size: 1.0625rem; max-width: 480px; }
.app-buttons { display: flex; gap: 12px; }
.app-btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 24px; background: var(--white); color: var(--green);
  border-radius: var(--radius-sm); font-weight: 600; font-size: 0.9375rem;
  transition: transform 0.2s;
}
.app-btn:hover { transform: translateY(-2px); }

/* ==================== GIFT PAGE ==================== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream-light) 0%, #fde8c8 100%);
  padding: 80px 0; text-align: center;
}
.gift-hero h1 { margin-bottom: 16px; color: var(--forest); }
.gift-hero p { font-size: 1.125rem; color: var(--gray-500); max-width: 560px; margin: 0 auto 32px; }

/* Carousel */
.carousel-section { margin-bottom: 56px; }
.carousel-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
.carousel-header h3 { color: var(--forest); }
.carousel-nav { display: flex; gap: 8px; }
.carousel-nav button {
  width: 40px; height: 40px; border-radius: 50%; border: 1.5px solid var(--gray-300);
  display: flex; align-items: center; justify-content: center; font-size: 1.125rem;
  color: var(--gray-600); transition: all 0.2s; background: var(--white);
}
.carousel-nav button:hover { border-color: var(--green); color: var(--green); background: var(--green-light); }

.carousel-track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex; gap: 16px; transition: transform 0.4s cubic-bezier(0.25, 0.1, 0.25, 1);
}
.gift-card {
  min-width: 200px; flex-shrink: 0; cursor: pointer;
  transition: transform 0.2s;
}
.gift-card:hover { transform: translateY(-4px); }
.gift-card-img {
  width: 200px; height: 130px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.8125rem; font-weight: 600; color: var(--white);
  margin-bottom: 8px; box-shadow: var(--shadow-md);
}
.gift-card-name { font-size: 0.8125rem; color: var(--gray-600); text-align: center; }

/* Category section */
.category-section { margin-bottom: 48px; }

/* Business gifting */
.business-gifting {
  display: flex; align-items: center; gap: 48px;
  padding: 56px; background: var(--forest); border-radius: var(--radius-xl); color: var(--cream-light);
}
.business-gifting h2 { color: var(--white); margin-bottom: 12px; }
.business-gifting p { opacity: 0.85; font-size: 1.0625rem; margin-bottom: 24px; max-width: 520px; }

/* eGift Info */
.egift-info { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start; }
.egift-text h3 { margin-bottom: 16px; color: var(--forest); }
.egift-text p { font-size: 0.9375rem; color: var(--gray-500); margin-bottom: 12px; }
.egift-links { display: flex; flex-wrap: wrap; gap: 16px; }
.egift-links a { color: var(--green); font-weight: 500; font-size: 0.9375rem; }
.egift-links a:hover { text-decoration: underline; }

/* FAQ */
.faq-list { max-width: 720px; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  width: 100%; padding: 20px 0; display: flex; justify-content: space-between;
  align-items: center; font-size: 1rem; font-weight: 500; color: var(--gray-700);
  text-align: left;
}
.faq-question .faq-icon { transition: transform 0.3s; font-size: 1.25rem; color: var(--gray-400); }
.faq-question.active .faq-icon { transform: rotate(45deg); }
.faq-answer { padding: 0 0 20px; font-size: 0.9375rem; color: var(--gray-500); display: none; }
.faq-answer.active { display: block; }

/* ==================== STORE LOCATOR ==================== */
.locator-layout { display: grid; grid-template-columns: 400px 1fr; min-height: calc(100vh - var(--header-height)); }
.locator-sidebar { background: var(--white); border-right: 1px solid var(--gray-200); display: flex; flex-direction: column; }

.search-controls { padding: 20px; border-bottom: 1px solid var(--gray-200); }
.search-input-wrap { display: flex; gap: 8px; margin-bottom: 12px; }
.search-input {
  flex: 1; padding: 12px 16px; border: 1.5px solid var(--gray-300); border-radius: var(--radius-full);
  font-size: 0.9375rem; outline: none; transition: border-color 0.2s;
}
.search-input:focus { border-color: var(--green); }
.search-input::placeholder { color: var(--gray-400); }
.search-btn {
  width: 44px; height: 44px; border-radius: 50%; background: var(--green);
  color: var(--white); display: flex; align-items: center; justify-content: center;
  font-size: 1.125rem; transition: background 0.2s;
}
.search-btn:hover { background: var(--green-dark); }

.search-filters { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.filter-btn {
  padding: 8px 16px; border-radius: var(--radius-full); border: 1.5px solid var(--gray-300);
  font-size: 0.8125rem; font-weight: 500; color: var(--gray-600); transition: all 0.2s;
  display: flex; align-items: center; gap: 4px;
}
.filter-btn:hover { border-color: var(--green); color: var(--green); }
.filter-btn.active { background: var(--green); color: var(--white); border-color: var(--green); }

.order-type-toggle {
  display: flex; background: var(--gray-100); border-radius: var(--radius-full); padding: 3px;
}
.order-type-btn {
  flex: 1; padding: 8px 20px; border-radius: var(--radius-full); font-size: 0.875rem;
  font-weight: 500; color: var(--gray-500); text-align: center; transition: all 0.2s;
}
.order-type-btn.active { background: var(--white); color: var(--green); box-shadow: var(--shadow-sm); }

.filter-panel {
  padding: 16px 20px; background: var(--off-white); border-bottom: 1px solid var(--gray-200);
  display: none;
}
.filter-panel.active { display: block; }
.filter-panel h4 { font-family: var(--font-body); font-weight: 600; font-size: 0.875rem; margin-bottom: 12px; color: var(--gray-700); }
.filter-options { display: flex; flex-wrap: wrap; gap: 8px; }
.filter-chip {
  padding: 6px 14px; border-radius: var(--radius-full); border: 1px solid var(--gray-300);
  font-size: 0.8125rem; color: var(--gray-600); cursor: pointer; transition: all 0.15s;
}
.filter-chip:hover { border-color: var(--green); color: var(--green); }
.filter-chip.selected { background: var(--green-light); border-color: var(--green); color: var(--green); font-weight: 500; }

/* Search Suggestions */
.search-suggestions {
  position: absolute; top: 100%; left: 0; right: 52px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg); display: none; z-index: 10; overflow: hidden;
}
.search-suggestions.active { display: block; }
.suggestion-item {
  padding: 12px 16px; font-size: 0.9375rem; color: var(--gray-600);
  cursor: pointer; transition: background 0.15s;
}
.suggestion-item:hover { background: var(--green-light); color: var(--green); }

/* Store Results */
.store-results { flex: 1; overflow-y: auto; padding: 8px 0; }
.store-result-item {
  padding: 16px 20px; border-bottom: 1px solid var(--gray-100);
  cursor: pointer; transition: background 0.15s;
}
.store-result-item:hover { background: var(--green-light); }
.store-result-item .store-name { font-weight: 600; font-size: 0.9375rem; color: var(--gray-700); margin-bottom: 4px; }
.store-result-item .store-address { font-size: 0.8125rem; color: var(--gray-500); margin-bottom: 4px; }
.store-result-item .store-hours { font-size: 0.8125rem; color: var(--green); }
.store-result-item .store-features { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.store-feature-tag {
  padding: 2px 8px; border-radius: var(--radius-full); font-size: 0.6875rem;
  background: var(--gray-100); color: var(--gray-500);
}

/* Map */
.map-view { background: var(--gray-100); position: relative; }
.map-placeholder {
  width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
  flex-direction: column; gap: 16px; color: var(--gray-400);
}
.map-placeholder-icon { font-size: 4rem; }
.map-pin {
  position: absolute; width: 32px; height: 32px; background: var(--green);
  border-radius: 50% 50% 50% 0; transform: rotate(-45deg);
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-md); cursor: pointer; transition: transform 0.2s;
}
.map-pin:hover { transform: rotate(-45deg) scale(1.2); }
.map-pin span { transform: rotate(45deg); color: var(--white); font-weight: 700; font-size: 0.75rem; }

/* ==================== RESPONSIVE ==================== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .menu-layout { grid-template-columns: 220px 1fr; }
  .menu-main { padding: 24px 32px; }
  .tier-cards { grid-template-columns: 1fr; max-width: 480px; margin: 0 auto; }
  .locator-layout { grid-template-columns: 340px 1fr; }
}

@media (max-width: 768px) {
  :root { --header-height: 60px; }

  .nav-primary, .nav-account { display: none; }
  .mobile-menu-btn { display: flex; }

  .hero { padding: 48px 0; }
  .hero-inner { flex-direction: column; text-align: center; }
  .hero-text p { margin-left: auto; margin-right: auto; }
  .hero-image { width: 100%; }
  .hero-image-placeholder { max-width: 320px; }

  .section { padding: 48px 0; }
  .promo-grid { grid-template-columns: 1fr; }
  .seasonal-split { grid-template-columns: 1fr; }
  .seasonal-image { min-height: 240px; }

  .how-it-works { grid-template-columns: 1fr; gap: 24px; }
  .partnership-grid { grid-template-columns: 1fr; }

  .app-download { flex-direction: column; text-align: center; padding: 40px 28px; }
  .app-download p { margin-left: auto; margin-right: auto; }
  .app-buttons { justify-content: center; }

  .redemption-card { flex-direction: column; text-align: center; }

  .egift-info { grid-template-columns: 1fr; }

  .business-gifting { flex-direction: column; text-align: center; padding: 40px 28px; }
  .business-gifting p { margin-left: auto; margin-right: auto; }

  /* Menu mobile */
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar {
    position: static; height: auto; border-right: none; border-bottom: 1px solid var(--gray-200);
    padding: 16px; overflow-x: auto; overflow-y: hidden; white-space: nowrap;
  }
  .menu-sidebar h4 { display: inline; margin: 0 16px 0 0; }
  .menu-sidebar a { display: inline; padding: 6px 12px; margin-right: 4px; }
  .menu-main { padding: 24px; }
  .breadcrumb { padding: 12px 24px; }

  /* Store locator mobile */
  .locator-layout { grid-template-columns: 1fr; }
  .map-view { height: 300px; order: -1; }
  .locator-sidebar { border-right: none; border-top: 1px solid var(--gray-200); }

  /* Gift page */
  .gift-card { min-width: 160px; }
  .gift-card-img { width: 160px; height: 104px; }

  /* Footer accordion on mobile */
  .footer-grid { grid-template-columns: 1fr; }
  .footer-accordion-toggle { display: flex; }
  .footer-col h4 { display: none; }
  .footer-col-content { max-height: 500px; }
  .footer-col-content.collapsed { max-height: 0; }

  .cookie-banner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .tab-btn { padding: 10px 14px; font-size: 0.8125rem; }
  .carousel-nav button { width: 36px; height: 36px; }
  .gift-card { min-width: 140px; }
  .gift-card-img { width: 140px; height: 91px; }
}

/* Print */
@media print {
  .site-header, .site-footer, .cookie-banner { display: none; }
  .section { padding: 24px 0; }
}
